const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const windhoek = ee.Geometry.Point([17.08, -22.56]);
  const region = windhoek.buffer(10000); // 10km radius around Windhoek

  // 2. Data Acquisition for February 2021 (Sentinel-2)
  let feb2021 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(region)
    .filterDate('2021-02-01', '2021-03-01')
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

  const size2021 = feb2021.size().getInfo();
  console.log(`Feb 2021 Images: ${size2021}`);

  if (size2021 === 0) {
    console.log('No Sentinel-2 data for Feb 2021, trying Landsat 8...');
    feb2021 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(region)
      .filterDate('2021-02-01', '2021-03-01');
    const sizeLandsat2021 = feb2021.size().getInfo();
    console.log(`Feb 2021 Landsat Images: ${sizeLandsat2021}`);
    if (sizeLandsat2021 === 0) {
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 3. Data Acquisition for 2010-2020 February Average (Landsat 7 & 8)
  const historical = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(region)
    .filter(ee.Filter.calendarRange(2, 2, 'month'))
    .filter(ee.Filter.calendarRange(2013, 2020, 'year'))
    .merge(
      ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
        .filterBounds(region)
        .filter(ee.Filter.calendarRange(2, 2, 'month'))
        .filter(ee.Filter.calendarRange(2010, 2020, 'year'))
    );

  const sizeHist = historical.size().getInfo();
  console.log(`Historical Feb Images (2010-2020): ${sizeHist}`);

  if (sizeHist === 0) {
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Processing - NDVI Calculation Functions
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask)
      .normalizedDifference(['B8', 'B4']).rename('NDVI');
  }

  function maskLandsatClouds(image) {
    const qaMask = image.select('QA_PIXEL').bitwiseAnd(parseInt('11111', 2)).eq(0);
    const saturationMask = image.select('QA_RADSAT').eq(0);
    const nir = image.select('SR_B5').multiply(0.0000275).add(-0.2);
    const red = image.select('SR_B4').multiply(0.0000275).add(-0.2);
    return image.updateMask(qaMask).updateMask(saturationMask)
      .addBands(nir.subtract(red).divide(nir.add(red)).rename('NDVI'))
      .select('NDVI');
  }

  // Process 2021 data
  let ndvi2021;
  if (size2021 > 0) {
    ndvi2021 = feb2021.map(maskS2clouds).median();
  } else {
    ndvi2021 = feb2021.map(maskLandsatClouds).median();
  }

  // Process historical data
  const ndviHistorical = historical.map(maskLandsatClouds).median();

  // 5. Calculate mean NDVI and pixel counts
  const stats2021 = ndvi2021.reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  });

  const statsHist = ndviHistorical.reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  });

  const mean2021 = stats2021.get('NDVI_mean').getInfo();
  const count2021 = stats2021.get('NDVI_count').getInfo();
  const meanHist = statsHist.get('NDVI_mean').getInfo();
  const countHist = statsHist.get('NDVI_count').getInfo();

  console.log(`Feb 2021: NDVI=${mean2021?.toFixed(3)}, Pixels=${count2021}`);
  console.log(`Feb 2010-2020 Avg: NDVI=${meanHist?.toFixed(3)}, Pixels=${countHist}`);

  // 6. Validation & Final Answer
  if (count2021 === 0 || countHist === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  if (mean2021 == null || meanHist == null || 
      mean2021 < -1 || mean2021 > 1 || 
      meanHist < -1 || meanHist > 1) {
    console.log('<answer>C3</answer>');
    return;
  }

  if (mean2021 > meanHist) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
